parameters.text:
=Run this Monday's CRM health check. Today is {{ $now.toISODate() }}.

Changes executed last week:
{{ $json.last_week }}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "action": {
      "type": "string",
      "description": "merge_companies | bulk_update_property | create_task | require_field | score_weight"
    },
    "target_ids": {
      "type": "string",
      "description": "JSON array of HubSpot record IDs this affects"
    },
    "details": {
      "type": "string",
      "description": "JSON object: for merge_companies { primary_id, merge_id, domain }; bulk_update_property { object_type, property, from_values, to_value }; create_task { deal_id, subject, owner_id }; require_field { stage, property }; score_weight { name, value, tested_on }"
    },
    "evidence": {
      "type": "string",
      "description": "what you found: counts, record IDs, examples"
    },
    "expected_effect": {
      "type": "string",
      "description": "what will improve"
    },
    "reversible": {
      "type": "boolean",
      "description": "true if the change can be undone"
    }
  },
  "required": [
    "action",
    "target_ids",
    "details",
    "evidence",
    "expected_effect",
    "reversible"
  ]
}

parameters.message:
=Proposal #{{ $json.id }}: {{ $json.action }}
Targets: {{ JSON.stringify($json.target_ids) }}
Details: {{ JSON.stringify($json.details) }}
Evidence: {{ $json.evidence }}
Expected: {{ $json.expected_effect }}
Reversible: {{ $json.reversible ? 'yes' : 'NO' }}
